     window->dictLimit = end;
 }

+/**
+ * ZSTD_window_init():
+ * Initialize a window to the state it should be in when it is first created.
+ * The first reference position starts at 1 (and not 0), so that the first
+ * input position is always a valid position for a match, even during the
+ * first usage of the context (see issue #1241).
+ */
+MEM_STATIC void ZSTD_window_init(ZSTD_window_t* window)
+{
+    memset(window, 0, sizeof(*window));
+    window->base = (BYTE const*)"";
+    window->dictBase = (BYTE const*)"";
+    window->dictLimit = 1;    /* start from 1, so that 1st position is valid */
+    window->lowLimit = 1;     /* it ensures first and later CCtx usages compare from a non-null prefix */
+    window->nextSrc = window->base + 1;   /* see issue #1241 */
+}
